def get_prediction(signal_data=None):
    """
    Selects a comedic prediction matching harmless face detection signals if present,
    or picks dynamically from the pool.
    """
    if signal_data and isinstance(signal_data, dict):
        sig = signal_data.get("harmless_signal", "")
        if sig == "smiling":
            candidates = [p for p in CAREER_PREDICTIONS if p["id"] in [
                "troll_admin", "startup_ceo", "software_engineer", "food_vlogger", "kalyana_broker"
            ]]
            if candidates:
                return random.choice(candidates)
        elif sig == "tilted":
            candidates = [p for p in CAREER_PREDICTIONS if p["id"] in [
                "autorickshaw_pilot", "lawyer", "crypto_trader", "uiux_designer"
            ]]
            if candidates:
                return random.choice(candidates)
        elif sig == "serious":
            candidates = [p for p in CAREER_PREDICTIONS if p["id"] in [
                "govt_officer", "doctor", "gulf_uncle", "psc_aspirant", "master_chef"
            ]]
            if candidates:
                return random.choice(candidates)

    return random.choice(CAREER_PREDICTIONS)
